#!/usr/bin/env bash
# Writes ./Caddyfile from the settings in .env (run from the project folder; install.sh and
# update.sh call it). Edit .env, not the generated file:
#   DOMAIN=chat.example.ir     the main address: a domain or an IP
#   TLS_MODE=auto              HTTPS for DOMAIN:
#                                auto     - Let's Encrypt (needs international internet to issue/renew)
#                                internal - this server's own certificate authority (fully offline;
#                                           devices install it once from http://<address>/ca)
#                                custom   - your own files ./certs/cert.pem and ./certs/key.pem
#                                off      - no HTTPS: plain HTTP only (chat works; calls and voice
#                                           chats need HTTPS: browsers only allow the microphone then)
#   ALSO_IP=1                  also answer on the server's IP (PUBLIC_IP): https://<ip> with the
#                              server's own certificate and plain http://<ip>, so it keeps working
#                              when the domain can't be resolved (e.g. its DNS is abroad)
#   ALLOW_HTTP=1               serve the app over plain http:// too instead of redirecting to https
# A Caddyfile without the "generated" marker below was written by hand and is left alone.
set -euo pipefail

MARK='# Generated by deploy/caddy-config.sh from .env'
val() { grep -E "^$1=" .env 2>/dev/null | tail -n1 | cut -d= -f2- | tr -d "\"'" | xargs || true; }
is_ip() { [[ "$1" =~ ^[0-9]+(\.[0-9]+){3}$ ]]; }

DOMAIN=$(val DOMAIN)
MODE=$(val TLS_MODE)
MODE=${MODE:-auto}
IP=$(val PUBLIC_IP)
ALSO_IP=$(val ALSO_IP)
ALLOW_HTTP=$(val ALLOW_HTTP)
[ -n "$DOMAIN" ] || { echo "!! DOMAIN is empty in .env"; exit 1; }
# Let's Encrypt can't be used for a bare IP: the server's own certificate instead.
if is_ip "$DOMAIN" && [ "$MODE" = "auto" ]; then MODE=internal; fi

if [ -f Caddyfile ] && ! grep -qF "$MARK" Caddyfile; then
  # A stock copy from an older version (only comments may differ) is replaced; a hand-edited one is kept.
  sum=$(grep -v '^\s*#' Caddyfile | tr -d ' \t\n' | sha256sum | cut -c1-64)
  case "$sum" in
    334a90d655fac68159f145c3cc44ad627e0520ceda98ef6f8cea2649ab93139a | 1a6b7a8cb570bef7f742d2353a38014cc090ee37b800df04ca13e7eb68296528 | \
      521a0302684650842e80790d6924693146a659dd3f8471a3517a44498423de50 | d3621790eaff7721d078305912a96c72de4795295d9fe17f83134e65fb15b112)
      cp Caddyfile Caddyfile.bak
      ;;
    *)
      if [ "${FORCE_CADDYFILE:-}" != "1" ]; then
        echo "!! Your Caddyfile was edited by hand, so it was kept. For the address options in .env, move it"
        echo "   away (e.g. mv Caddyfile Caddyfile.mine) and run: sudo bash deploy/caddy-config.sh"
        exit 0
      fi
      cp Caddyfile Caddyfile.bak
      ;;
  esac
fi

plain_extras='	# The CA download (must work before a device trusts the CA) and the Android app download.
	handle /ca.crt {
		root * /data/caddy/pki/authorities/local
		rewrite * /root.crt
		header Content-Type application/x-x509-ca-cert
		header Content-Disposition "attachment; filename=amorechat-ca.crt"
		file_server
	}
	handle /ca {
		rewrite * /ca-help
		reverse_proxy app:3000
	}
	handle /app* {
		reverse_proxy app:3000
	}'

app_block='	handle {
		encode zstd gzip
		reverse_proxy app:3000
	}'

tls_line() {
  case "$1" in
    internal) echo '	tls internal' ;;
    custom) echo '	tls /certs/cert.pem /certs/key.pem' ;;
    *) ;;
  esac
}

{
  echo "$MARK"
  echo "# (DOMAIN=$DOMAIN TLS_MODE=$MODE ALSO_IP=${ALSO_IP:-0} ALLOW_HTTP=${ALLOW_HTTP:-0}). Edit .env, then: sudo amorechat-update"
  echo '{'
  echo '	# Browsers send no server name when you open https://<ip>: use the certificate of that IP.'
  if is_ip "$DOMAIN"; then
    echo "	default_sni $DOMAIN"
  elif [ "$ALSO_IP" = "1" ] && [ -n "$IP" ]; then
    echo "	default_sni $IP"
  else
    echo "	default_sni $DOMAIN"
  fi
  echo '}'
  echo

  # Main address
  if [ "$MODE" != "off" ]; then
    echo "$DOMAIN {"
    tls_line "$MODE"
    echo '	encode zstd gzip'
    echo '	reverse_proxy app:3000'
    echo '}'
    echo
  fi
  echo "http://$DOMAIN {"
  echo "$plain_extras"
  if [ "$MODE" = "off" ] || [ "$ALLOW_HTTP" = "1" ]; then
    echo "$app_block"
  else
    echo '	handle {'
    echo '		redir https://{host}{uri} permanent'
    echo '	}'
  fi
  echo '}'

  # The server's IP as a second address
  if [ "$ALSO_IP" = "1" ] && [ -n "$IP" ] && [ "$IP" != "$DOMAIN" ]; then
    echo
    echo '# Second address: the IP (works without DNS)'
    echo "https://$IP {"
    echo '	tls internal'
    echo '	encode zstd gzip'
    echo '	reverse_proxy app:3000'
    echo '}'
    echo
    echo "http://$IP {"
    echo "$plain_extras"
    echo "$app_block"
    echo '}'
  fi
} > Caddyfile.new
mv Caddyfile.new Caddyfile
extra=''
if [ "$ALSO_IP" = "1" ] && [ -n "$IP" ] && [ "$IP" != "$DOMAIN" ]; then extra=" + $IP"; fi
echo ">> Caddyfile: $DOMAIN ($MODE)$extra"
